L000322	  \label{highpfit}
L000323	\end{figure}
L000324	\begin{figure}[t]
L000325	  \centering
L000326	  \includegraphics[width=8.1cm]{figs/fig2.eps}
L000327	  \caption{(a) The $\gamma\gamma$ invariant mass spectrum in the low-momentum sample with the fit result. The notation of lines is the same as that in Fig.~\ref{highpfit}. The green hatched area indicates the mass region excluded from the fit. (b) The residuals divided by statistical uncertainties in each bin for the fit in panel (a).}
L000328	  \label{bgonlyfit}
